package org.canpshell.mobile;
import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.util.concurrent.*;
/** Bounded TCP-only SOCKS5 ingress. DNS names are sent to the selected remote HTTP CONNECT exit. */
final class AndroidVpnSocks implements AutoCloseable {
 interface Exit {int port()throws IOException;}
 private final Exit exit;private final ServerSocket listener;private final Set<Socket> sockets=ConcurrentHashMap.newKeySet();private final ExecutorService pool=Executors.newFixedThreadPool(64);private volatile boolean closed;
 AndroidVpnSocks(Exit exit)throws IOException{this.exit=exit;listener=new ServerSocket();listener.bind(new InetSocketAddress("127.0.0.1",0),16);Thread accept=new Thread(()->{while(!closed)try{Socket s=listener.accept();if(sockets.size()>=48){s.close();continue;}sockets.add(s);pool.execute(()->serve(s));}catch(Exception e){if(!closed)close();}},"cagent-vpn-socks");accept.setDaemon(true);accept.start();}
 int port(){return listener.getLocalPort();}
 static byte[] read(InputStream in,int n)throws IOException{byte[] b=new byte[n];int at=0;while(at<n){int count=in.read(b,at,n-at);if(count<0)throw new EOFException();at+=count;}return b;}
 private void serve(Socket client){Socket upstream=null;boolean established=false;try{client.setSoTimeout(10000);InputStream in=client.getInputStream();OutputStream out=client.getOutputStream();byte[] hello=read(in,2);if(hello[0]!=5)throw new IOException("Invalid SOCKS");boolean noAuth=false;for(byte m:read(in,hello[1]&255))if(m==0)noAuth=true;if(!noAuth){out.write(new byte[]{5,(byte)255});return;}out.write(new byte[]{5,0});byte[] request=read(in,4);if(request[0]!=5||request[1]!=1||request[2]!=0){out.write(new byte[]{5,7,0,1,0,0,0,0,0,0});return;}String host;int type=request[3]&255;if(type==1)host=InetAddress.getByAddress(read(in,4)).getHostAddress();else if(type==4)host="["+InetAddress.getByAddress(read(in,16)).getHostAddress()+"]";else if(type==3){int n=read(in,1)[0]&255;if(n==0)throw new IOException("Empty host");host=new String(read(in,n),StandardCharsets.US_ASCII);if(!host.matches("[A-Za-z0-9._-]+"))throw new IOException("Invalid host");}else throw new IOException("Invalid address");byte[] p=read(in,2);int port=((p[0]&255)<<8)|(p[1]&255);if(port==0)throw new IOException("Invalid port");
 upstream=new Socket();sockets.add(upstream);upstream.connect(new InetSocketAddress("127.0.0.1",exit.port()),10000);upstream.setSoTimeout(15000);OutputStream remote=upstream.getOutputStream();String authority=host+":"+port;remote.write(("CONNECT "+authority+" HTTP/1.1\r\nHost: "+authority+"\r\n\r\n").getBytes(StandardCharsets.US_ASCII));InputStream reply=upstream.getInputStream();ByteArrayOutputStream header=new ByteArrayOutputStream();int state=0;while(header.size()<16384&&state<4){int b=reply.read();if(b<0)throw new EOFException();header.write(b);state=(state==0&&b==13)?1:(state==1&&b==10)?2:(state==2&&b==13)?3:(state==3&&b==10)?4:0;}String response=new String(header.toByteArray(),StandardCharsets.US_ASCII);if(state!=4||!response.matches("(?s)HTTP/1\\.[01] 200(?: |\\r).*"))throw new IOException("Exit refused connection");
 out.write(new byte[]{5,0,0,1,0,0,0,0,0,0});established=true;client.setSoTimeout(120000);upstream.setSoTimeout(120000);Socket remoteSocket=upstream;Future<?> sending=pool.submit(()->{try{copy(in,remote);remoteSocket.shutdownOutput();}catch(IOException e){quiet(remoteSocket);quiet(client);}});copy(reply,out);client.shutdownOutput();try{sending.get(2,TimeUnit.SECONDS);}catch(Exception ignored){sending.cancel(true);}
 }catch(Exception e){if(!established)try{client.getOutputStream().write(new byte[]{5,1,0,1,0,0,0,0,0,0});}catch(Exception ignored){}}finally{quiet(client);sockets.remove(client);if(upstream!=null){quiet(upstream);sockets.remove(upstream);}}}
 private static void copy(InputStream in,OutputStream out)throws IOException{byte[] b=new byte[16384];for(int n;(n=in.read(b))>=0;)if(n>0)out.write(b,0,n);}
 private static void quiet(Socket s){try{s.close();}catch(IOException ignored){}}
 public void close(){closed=true;try{listener.close();}catch(IOException ignored){}for(Socket s:sockets)quiet(s);sockets.clear();pool.shutdownNow();}
}
